-- System contract templates and their clauses were only ever created by
-- supabase/seed.sql, so environments migrated without seeding (production) had
-- none and the contract wizard failed with "No template for residential".
-- Seed them once here; the guard keeps re-runs and seeded databases untouched.
do $seed_templates$
begin
if not exists (select 1 from public.contract_templates where org_id is null) then
انه في يوم {{day_name}} الموافق {{contract_date}}
تم الاتفاق بين كل من:
الطرف الأول: {{owner_name}}، المالك
ويحمل بطاقة مدنية رقم: {{owner_civil_id}}
الطرف الثاني: {{tenant_name}}، المستأجر
بطاقة مدنية: {{tenant_civil_id}}، تليفون: {{tenant_phones}}
حيث إن الطرف الأول يستغل {{property_description}} الرقم الآلي للعنوان {{property_paci}}
تم الاتفاق وذلك وفق الشروط التالية:', null, true),
  ('2d000000-0000-4000-8000-000000000002', null, 'investment', 'عقد إيجار استثماري', 1, '2d000000-0000-4000-8000-000000000002', 'عقد إيجار
انه في يوم {{day_name}} الموافق {{contract_date}}
تم الاتفاق بين كل من:
الطرف الأول: {{owner_name}}، المالك
